package org.apache.commons.lang.enums;

import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ClassUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for ValuedEnum#compareTo
 */
public class ValuedEnum_compareTo_TriageGen0Test {

    /**
     * Concrete implementation of ValuedEnum for testing purposes.
     * Since the constructor is protected, we create a local subclass.
     */
    private static class TestValuedEnum extends ValuedEnum {
        protected TestValuedEnum(String name, int value) {
            super(name, value);
        }
    }

    @Test
    public void testCompareTo_SameValue() {
        ValuedEnum enum1 = new TestValuedEnum("A", 10);
        ValuedEnum enum2 = new TestValuedEnum("B", 10);

        // 10 - 10 = 0
        assertEquals(0, enum1.compareTo(enum2));
    }

    @Test
    public void testCompareTo_GreaterValue() {
        ValuedEnum enum1 = new TestValuedEnum("A", 20);
        ValuedEnum enum2 = new TestValuedEnum("B", 10);

        // 20 - 10 = 10
        assertEquals(10, enum1.compareTo(enum2));
    }

    @Test
    public void testCompareTo_LessValue() {
        ValuedEnum enum1 = new TestValuedEnum("A", 5);
        ValuedEnum enum2 = new TestValuedEnum("B", 15);

        // 5 - 15 = -10
        assertEquals(-10, enum1.compareTo(enum2));
    }

    @Test(expected = ClassCastException.class)
    public void testCompareTo_WrongType() {
        ValuedEnum enum1 = new TestValuedEnum("A", 10);
        // Passing a String instead of a ValuedEnum should trigger ClassCastException
        // due to ((ValuedEnum) other) cast in the method.
        enum1.compareTo("NotAnEnum");
    }

    @Test(expected = NullPointerException.class)
    public void testCompareTo_Null() {
        ValuedEnum enum1 = new TestValuedEnum("A", 10);
        // Passing null will trigger NullPointerException during unboxing or casting
        enum1.compareTo(null);
    }
}
